<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { buscarItems, listarMovimientos, obtenerDetalle, urlReporteMovimientos, type ItemOption, type Movimiento, type MovimientoDocumento, type MovimientoItem } from '../services/movimientos'
import type { CatalogoSaldo } from '../services/saldos'
const rows=ref<Movimiento[]>([]),almacenes=ref<CatalogoSaldo[]>([]),options=ref<ItemOption[]>([]),selected=ref<ItemOption[]>([]),itemSearch=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),modo=ref<'documento'|'item'>('documento'),loading=ref(false),error=ref(''),detail=ref<MovimientoItem[]|null>(null),summary=reactive({ingresos:0,salidas:0,documentos:0,anulados:0}),filters=reactive({almacen:'',desde:'',hasta:''})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarMovimientos({...filters,items:selected.value.map(x=>x.id),page:next});rows.value=r.data;almacenes.value=r.almacenes;lastPage.value=r.last_page;total.value=r.total;modo.value=r.modo;Object.assign(summary,r.resumen);if(!filters.almacen&&r.almacen_default_id)filters.almacen=String(r.almacen_default_id);if(!filters.desde&&r.periodo){filters.desde=r.periodo.fecha_inicio;filters.hasta=r.periodo.fecha_fin}}catch(e){error.value=message(e)}finally{loading.value=false}}
async function search(){if(!itemSearch.value.trim())return;try{options.value=await buscarItems(itemSearch.value)}catch(e){error.value=message(e)}}
function add(item:ItemOption){if(!selected.value.some(x=>x.id===item.id))selected.value.push(item);itemSearch.value='';options.value=[]}
async function show(row:MovimientoDocumento){try{detail.value=await obtenerDetalle(row.movimiento_id,row.almacen_id)}catch(e){error.value=message(e)}}
const money=(v=0)=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v),number=(v=0)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudieron consultar los movimientos.'
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Movimientos</nav><header class="hero"><div class="mark">MV</div><div><small>MIA · ALMACÉN</small><h1>Movimientos de almacén</h1><p>Audita ingresos, salidas y saldos resultantes.</p></div><a :href="urlReporteMovimientos({...filters,items:selected.map(x=>x.id)})" target="_blank">Generar PDF</a></header><p v-if="error" class="flash">{{error}}</p><section class="metrics"><article><small>DOCUMENTOS</small><b>{{summary.documentos}}</b></article><article class="in"><small>INGRESOS</small><b>{{number(summary.ingresos)}}</b></article><article class="out"><small>SALIDAS</small><b>{{number(summary.salidas)}}</b></article><article class="bad"><small>ANULADOS</small><b>{{summary.anulados}}</b></article></section>
<section class="filters"><label>Almacén<select v-model="filters.almacen"><option value="">Seleccione</option><option v-for="x in almacenes" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Desde<input v-model="filters.desde" type="date"></label><label>Hasta<input v-model="filters.hasta" type="date"></label><div class="item-picker"><label>Ítems (opcional)<span><input v-model.trim="itemSearch" placeholder="Buscar ítem" @keyup.enter="search"><button @click="search">Buscar</button></span></label><div v-if="options.length" class="results"><button v-for="x in options" :key="x.id" @click="add(x)">#{{x.id}} · {{x.nombre}}</button></div><div class="chips"><button v-for="x in selected" :key="x.id" @click="selected=selected.filter(y=>y.id!==x.id)">{{x.nombre}} ×</button></div></div><button class="submit" @click="load(1)">Consultar</button></section>
<section class="table-card"><header><div><small>{{modo==='item'?'DETALLE POR ÍTEM':'DOCUMENTOS DE ALMACÉN'}}</small><h2>{{modo==='item'?'Movimientos valorizados':'Listado de movimientos'}}</h2></div><b>{{total}} resultados</b></header><div v-if="loading" class="empty">Consultando movimientos…</div><div v-else-if="!rows.length" class="empty">No existen movimientos para el rango seleccionado.</div><div v-else class="scroll"><table v-if="modo==='documento'"><thead><tr><th>Código</th><th>Fecha</th><th>Movimiento</th><th>Ítems</th><th>Orden</th><th>Pedido</th><th>Referencia</th><th>Descripción</th><th></th></tr></thead><tbody><tr v-for="raw in rows" :key="(raw as MovimientoDocumento).movimiento_id" :class="{cancelled:(raw as MovimientoDocumento).estado_movimiento===1}"><template v-if="raw.modo==='documento'"><td>#{{raw.movimiento_id}}</td><td>{{raw.fecha}}</td><td><span class="badge">{{raw.movimiento}}</span></td><td>{{raw.cantidad}}</td><td>{{raw.orden_compra||'SIN ORDEN'}}</td><td>{{raw.pedido||'SIN PEDIDO'}}</td><td>{{raw.referencia||raw.doc_referencia||'—'}}</td><td>{{raw.descripcion||'—'}}</td><td><button class="link" @click="show(raw)">Detalle</button></td></template></tr></tbody></table><table v-else><thead><tr><th>Fecha</th><th>Ítem</th><th>Unidad</th><th>Tipo</th><th class="right">Cantidad</th><th class="right">V. unitario</th><th class="right">Valor total</th><th class="right">Saldo</th><th>Glosa</th></tr></thead><tbody><tr v-for="raw in rows" :key="(raw as MovimientoItem).id" :class="{cancelled:(raw as MovimientoItem).estado_movimiento===1}"><template v-if="raw.modo==='item'"><td>{{raw.fecha}}</td><td><b>{{raw.nombre_item}}</b></td><td>{{raw.unidad_item}}</td><td><span class="badge" :class="raw.tipo_movimiento.toLowerCase()">{{raw.tipo_movimiento}}</span></td><td class="right">{{number(raw.cantidad)}}</td><td class="right">{{money(raw.valor_unitario)}}</td><td class="right">{{money(raw.valor_total)}}</td><td class="right"><b>{{number(raw.saldo_cantidad)}}</b></td><td>{{raw.glosa_movimiento}}</td></template></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog"><header><div><small>DETALLE DEL DOCUMENTO</small><h2>Movimientos registrados</h2></div><button @click="detail=null">×</button></header><table><thead><tr><th>Ítem</th><th>Tipo</th><th>Cantidad</th><th>Valor unitario</th><th>Total</th><th>Saldo</th></tr></thead><tbody><tr v-for="x in detail" :key="x.id"><td>{{x.nombre_item}}</td><td>{{x.tipo_movimiento}}</td><td>{{number(x.cantidad)}}</td><td>{{money(x.valor_unitario)}}</td><td>{{money(x.valor_total)}}</td><td>{{number(x.saldo_cantidad)}}</td></tr></tbody></table><footer><button @click="detail=null">Cerrar</button></footer></section></div></div></template>
